#!/bin/bash
echo "This is a test script, received args: $*"

#
# Check if we are running under fakeroot which is a must
#
function check_if_fakeroot() {
	echo -n "Check: Running under fakeroot?"
	[ -z "${FAKEROOTKEY}" ] && echo "no" && exit 1;
	echo yes, FAKEROOTKEY: $FAKEROOTKEY
}
function copy_new_app() {
	cp ./server.bin $1/usr/bin/
	echo -n "tcpClient1 &" >> $1/etc/rc.d/rc.local
}
#
# Main function
#
function main() {
	check_if_fakeroot
	copy_new_app $1
	exit 0;
}

###############################################################################
main $*

var serverIP = "11.0.0.1";
var serverPort = 5679;
var client;

function main() {
	client = new TCPClient();
	client.onConnectionChanged = function(type) {
		Device.println("connection changed: " + type);
	};

	client.onData = function(data) {
		Device.println("My IP: " + client.localIP() + ":" + client.localPort());
		Device.println("Server IP: "  + client.remoteIP() + ":" + client.remotePort());
		Device.println("received from server: " + data);
		client.send("I'm client1");
	};

	// connect to server
	client.connect(serverIP, serverPort);
}

