#!/bin/bash
echo "This is a test script, received args: $*"

#
# Check if we are running under fakeroot which is a must
#
function check_if_fakeroot() {
	echo -n "Check: Running under fakeroot?"
	[ -z "${FAKEROOTKEY}" ] && echo "no" && exit 1;
	echo yes, FAKEROOTKEY: $FAKEROOTKEY
}
function copy_new_app() {
	cp ./server.bin $1/usr/bin/
	echo -n "tcpServer &" >> $1/etc/rc.d/rc.local
}
#
# Main function
#
function main() {
	check_if_fakeroot
	copy_new_app $1
	exit 0;
}

###############################################################################
main $*

var port = 5679;
var server;

function main() {
	server = new TCPServer();

	server.onNewClient = function(client) {
		Device.println("new client: " + client.remoteIP() + ":" + client.remotePort());
		client.onConnectionChanged = function(type) {
			Device.println("connection changed: " + type);
		};

		client.onData = function(data) {
			Device.println("received from " + client.remoteIP() + ":" + client.remotePort() + ", Data: " + data);
			//client.close();
		};

		client.send("Greeting from " + client.localIP() + ":" + client.localPort());
	};

	server.listen(port);
}

